package com.gabrieltagama.menuplanner.core.data.database

import androidx.room.testing.MigrationTestHelper
import androidx.sqlite.db.SupportSQLiteDatabase
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

/**
 * Tests of the Room schema history. Uses the exported schema JSON of every version
 * (core/data/schemas/...): 1.json is committed and the current one is generated by the Room
 * Gradle plugin at build time; the androidTest assets include both. Each migration is run with
 * runMigrationsAndValidate, which also checks the result against the current entities.
 */
@RunWith(AndroidJUnit4::class)
class MigrationTest {

    @get:Rule
    val helper = MigrationTestHelper(
        InstrumentationRegistry.getInstrumentation(),
        MenuPlannerDatabase::class.java
    )

    @Test
    fun createsVersion1WithExpectedTables() {
        helper.createDatabase(TEST_DB, 1).use { db ->
            insertVersion1Rows(db)

            assertEquals(1, db.version)
            db.query("SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('dishes', 'ingredients', 'meal_days')").use { cursor ->
                assertEquals(3, cursor.count)
            }
            db.query("SELECT COUNT(*) FROM meal_days WHERE single_id = 'd1'").use { cursor ->
                assertTrue(cursor.moveToFirst())
                assertEquals(1, cursor.getInt(0))
            }
        }
    }

    @Test
    fun migrate1To2KeepsDataAndAddsRatingAndMealTimeDefaults() {
        helper.createDatabase(TEST_DB, 1).use(::insertVersion1Rows)

        helper.runMigrationsAndValidate(TEST_DB, 2, true, Migrations.MIGRATION_1_2).use { db ->
            db.query("SELECT name, rating, meal_time FROM dishes WHERE id = 'd1'").use { cursor ->
                assertTrue(cursor.moveToFirst())
                assertEquals("Soup", cursor.getString(0))
                assertEquals("THREE", cursor.getString(1))
                assertEquals("ANY", cursor.getString(2))
            }
            db.query("SELECT COUNT(*) FROM meal_days WHERE single_id = 'd1'").use { cursor ->
                assertTrue(cursor.moveToFirst())
                assertEquals(1, cursor.getInt(0))
            }
        }
    }

    @Test
    fun registeredMigrationsMatchCurrentVersion() =
        assertEquals(listOf(Migrations.MIGRATION_1_2), Migrations.ALL.toList())

    private fun insertVersion1Rows(db: SupportSQLiteDatabase) {
        db.execSQL("INSERT INTO dishes (id, name, description, preparation, type, heaviness, updated_at) VALUES ('d1', 'Soup', '', '', 'STARTER', 'VERY_LOW', 1)")
        db.execSQL("INSERT INTO ingredients (dish_id, position, name, quantity, unit) VALUES ('d1', 0, 'Water', 1.0, 'LITER')")
        db.execSQL("INSERT INTO meal_days (date, starter_id, main_id, single_id, dessert_id, updated_at) VALUES (20000, NULL, NULL, 'd1', NULL, 1)")
    }

    private companion object {
        const val TEST_DB = "migration-test.db"
    }
}
